//! Database character sets → UTF-8 (REQ-002.4). **Owner: Lead.**
//!
//! Contract:
//! * [`decode`] never guesses. Bytes that are not valid in the declared
//!   character set are replaced by U+FFFD **and** reported: the caller keeps
//!   the raw bytes next to the text, so nothing is ever lost silently.
//! * Single-byte tables are generated by `tools/gen_charsets.py` from
//!   unicode.org files and cross-checked against WHATWG / Python before use.
//! * Oracle `UTF8` is CESU-8 (supplementary characters stored as two 3-byte
//!   surrogates); `AL32UTF8` is standard UTF-8. They are decoded separately.
//! * `AL16UTF16` (the default national character set for `NCHAR`/`NVARCHAR2`)
//!   is UTF-16 **big-endian on every platform**.
//!
//! Charset ids are those returned by Oracle's `NLS_CHARSET_ID()` and stored in
//! the dictionary (`props$`, `col$.charsetid`) — `lab-verify` LV-011.

#[rustfmt::skip]
mod tables;

use std::borrow::Cow;

/// A database / national character set supported by ODR.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Charset {
    /// `US7ASCII` (id 1).
    Us7Ascii,
    /// `WE8ISO8859P1` (id 31).
    We8Iso8859P1,
    /// `WE8MSWIN1252` (id 178).
    We8MsWin1252,
    /// `AR8ISO8859P6` (id 51).
    Ar8Iso8859P6,
    /// `AR8MSWIN1256` (id 560) — the usual Arabic Windows database charset.
    Ar8MsWin1256,
    /// `UTF8` (id 871) — Oracle's CESU-8.
    Utf8Cesu,
    /// `AL32UTF8` (id 873) — standard UTF-8.
    Al32Utf8,
    /// `AL16UTF16` (id 2000) — UTF-16BE, national character set.
    Al16Utf16,
}

impl Charset {
    /// Map an Oracle charset id (`NLS_CHARSET_ID`) to a supported charset.
    pub const fn from_oracle_id(id: u16) -> Option<Self> {
        Some(match id {
            1 => Self::Us7Ascii,
            31 => Self::We8Iso8859P1,
            51 => Self::Ar8Iso8859P6,
            178 => Self::We8MsWin1252,
            560 => Self::Ar8MsWin1256,
            871 => Self::Utf8Cesu,
            873 => Self::Al32Utf8,
            2000 => Self::Al16Utf16,
            _ => return None,
        })
    }

    /// Map an Oracle charset name (case-insensitive).
    pub fn from_oracle_name(name: &str) -> Option<Self> {
        Some(match name.to_ascii_uppercase().as_str() {
            "US7ASCII" => Self::Us7Ascii,
            "WE8ISO8859P1" => Self::We8Iso8859P1,
            "WE8MSWIN1252" => Self::We8MsWin1252,
            "AR8ISO8859P6" => Self::Ar8Iso8859P6,
            "AR8MSWIN1256" => Self::Ar8MsWin1256,
            "UTF8" => Self::Utf8Cesu,
            "AL32UTF8" => Self::Al32Utf8,
            "AL16UTF16" => Self::Al16Utf16,
            _ => return None,
        })
    }

    /// Oracle name.
    pub const fn oracle_name(self) -> &'static str {
        match self {
            Self::Us7Ascii => "US7ASCII",
            Self::We8Iso8859P1 => "WE8ISO8859P1",
            Self::We8MsWin1252 => "WE8MSWIN1252",
            Self::Ar8Iso8859P6 => "AR8ISO8859P6",
            Self::Ar8MsWin1256 => "AR8MSWIN1256",
            Self::Utf8Cesu => "UTF8",
            Self::Al32Utf8 => "AL32UTF8",
            Self::Al16Utf16 => "AL16UTF16",
        }
    }

    fn single_byte_table(self) -> Option<&'static [u16; 128]> {
        match self {
            Self::We8Iso8859P1 => Some(&tables::ISO8859_1),
            Self::We8MsWin1252 => Some(&tables::CP1252),
            Self::Ar8Iso8859P6 => Some(&tables::ISO8859_6),
            Self::Ar8MsWin1256 => Some(&tables::CP1256),
            _ => None,
        }
    }
}

/// Result of decoding one value.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Decoded<'a> {
    /// UTF-8 text; borrowed when the input was already valid ASCII/UTF-8.
    pub text: Cow<'a, str>,
    /// Number of invalid sequences replaced by U+FFFD. `0` = exact.
    pub invalid: usize,
}

impl Decoded<'_> {
    /// Whether the conversion was lossless.
    pub const fn is_exact(&self) -> bool {
        self.invalid == 0
    }
}

/// Decode `raw` (column bytes) from `cs` to UTF-8.
pub fn decode(raw: &[u8], cs: Charset) -> Decoded<'_> {
    // Fast path: pure ASCII is identical in every supported 8-bit/UTF-8 set.
    if cs != Charset::Al16Utf16 && raw.is_ascii() {
        return Decoded {
            text: Cow::Borrowed(ascii_str(raw)),
            invalid: 0,
        };
    }
    match cs {
        Charset::Us7Ascii => decode_ascii(raw),
        Charset::Al32Utf8 => decode_utf8(raw),
        Charset::Utf8Cesu => decode_cesu8(raw),
        Charset::Al16Utf16 => decode_utf16be(raw),
        _ => decode_single_byte(raw, cs.single_byte_table().unwrap_or(&tables::ISO8859_1)),
    }
}

fn ascii_str(raw: &[u8]) -> &str {
    // Caller checked `is_ascii`, so this never fails; fall back to "" defensively.
    std::str::from_utf8(raw).unwrap_or_default()
}

fn decode_ascii(raw: &[u8]) -> Decoded<'_> {
    let mut invalid = 0usize;
    let text: String = raw
        .iter()
        .map(|&b| {
            if b.is_ascii() {
                char::from(b)
            } else {
                invalid = invalid.saturating_add(1);
                char::REPLACEMENT_CHARACTER
            }
        })
        .collect();
    Decoded {
        text: Cow::Owned(text),
        invalid,
    }
}

fn decode_single_byte<'a>(raw: &'a [u8], table: &[u16; 128]) -> Decoded<'a> {
    let mut invalid = 0usize;
    let mut s = String::with_capacity(raw.len().saturating_mul(2));
    for &b in raw {
        if b.is_ascii() {
            s.push(char::from(b));
            continue;
        }
        let u = table.get(usize::from(b & 0x7F)).copied().unwrap_or(0);
        match char::from_u32(u32::from(u)) {
            Some(c) if u != 0 => s.push(c),
            _ => {
                invalid = invalid.saturating_add(1);
                s.push(char::REPLACEMENT_CHARACTER);
            }
        }
    }
    Decoded {
        text: Cow::Owned(s),
        invalid,
    }
}

fn decode_utf8(raw: &[u8]) -> Decoded<'_> {
    if let Ok(s) = std::str::from_utf8(raw) {
        return Decoded {
            text: Cow::Borrowed(s),
            invalid: 0,
        };
    }
    let mut invalid = 0usize;
    let mut s = String::with_capacity(raw.len());
    for chunk in raw.utf8_chunks() {
        s.push_str(chunk.valid());
        if !chunk.invalid().is_empty() {
            invalid = invalid.saturating_add(1);
            s.push(char::REPLACEMENT_CHARACTER);
        }
    }
    Decoded {
        text: Cow::Owned(s),
        invalid,
    }
}

/// CESU-8: like UTF-8 but supplementary characters are a UTF-16 surrogate
/// pair, each encoded as a 3-byte sequence `ED A0..AF xx` / `ED B0..BF xx`.
fn decode_cesu8(raw: &[u8]) -> Decoded<'_> {
    // Without any 0xED lead byte, CESU-8 and UTF-8 coincide exactly.
    if !raw.contains(&0xED) {
        return decode_utf8(raw);
    }
    let mut units: Vec<u16> = Vec::with_capacity(raw.len());
    let mut invalid = 0usize;
    let mut out = String::with_capacity(raw.len());
    let mut i = 0;
    let flush = |units: &mut Vec<u16>, out: &mut String, invalid: &mut usize| {
        for r in char::decode_utf16(units.drain(..)) {
            out.push(r.unwrap_or_else(|_| {
                *invalid = (*invalid).saturating_add(1);
                char::REPLACEMENT_CHARACTER
            }));
        }
    };
    while let Some(&lead) = raw.get(i) {
        let need = match lead {
            0x00..=0x7F => 1,
            0xC2..=0xDF => 2,
            0xE0..=0xEF => 3,
            _ => 0,
        };
        let seq = raw.get(i..i.saturating_add(need)).filter(|_| need > 0);
        let cp = seq.and_then(|s| match *s {
            [b0] => Some(u32::from(b0)),
            [b0, b1] if b1 & 0xC0 == 0x80 => {
                Some((u32::from(b0 & 0x1F) << 6) | u32::from(b1 & 0x3F))
            }
            [b0, b1, b2] if b1 & 0xC0 == 0x80 && b2 & 0xC0 == 0x80 => {
                let v = (u32::from(b0 & 0x0F) << 12)
                    | (u32::from(b1 & 0x3F) << 6)
                    | u32::from(b2 & 0x3F);
                // Reject overlong 3-byte forms.
                (v >= 0x800).then_some(v)
            }
            _ => None,
        });
        if let Some(v) = cp {
            units.push(u16::try_from(v).unwrap_or(0xFFFD));
            i = i.saturating_add(need);
        } else {
            flush(&mut units, &mut out, &mut invalid);
            invalid = invalid.saturating_add(1);
            out.push(char::REPLACEMENT_CHARACTER);
            i = i.saturating_add(1);
        }
    }
    flush(&mut units, &mut out, &mut invalid);
    Decoded {
        text: Cow::Owned(out),
        invalid,
    }
}

fn decode_utf16be(raw: &[u8]) -> Decoded<'_> {
    let (pairs, rest) = raw.as_chunks::<2>();
    let mut invalid = usize::from(!rest.is_empty());
    let mut s: String = char::decode_utf16(pairs.iter().map(|p| u16::from_be_bytes(*p)))
        .map(|r| {
            r.unwrap_or_else(|_| {
                invalid = invalid.saturating_add(1);
                char::REPLACEMENT_CHARACTER
            })
        })
        .collect();
    if !rest.is_empty() {
        s.push(char::REPLACEMENT_CHARACTER);
    }
    Decoded {
        text: Cow::Owned(s),
        invalid,
    }
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::indexing_slicing)]
mod tests {
    use super::*;

    fn d(raw: &[u8], cs: Charset) -> (String, usize) {
        let r = decode(raw, cs);
        (r.text.into_owned(), r.invalid)
    }

    #[test]
    fn arabic_win1256() {
        // "محمد علي — ٢٠٢٦" typed on an Arabic Windows client into AR8MSWIN1256.
        let raw = [0xE3, 0xCD, 0xE3, 0xCF, 0x20, 0xDA, 0xE1, 0xED];
        assert_eq!(d(&raw, Charset::Ar8MsWin1256), ("محمد علي".into(), 0));
        // Arabic comma 0xA1, semicolon 0xBA, question mark 0xBF, tatweel 0xDC.
        assert_eq!(
            d(&[0xA1, 0xBA, 0xBF, 0xDC], Charset::Ar8MsWin1256),
            ("،؛؟ـ".into(), 0)
        );
        // Persian/Urdu letters present in 1256 but not 8859-6: پ چ ژ گ
        assert_eq!(
            d(&[0x81, 0x8D, 0x8E, 0x90], Charset::Ar8MsWin1256),
            ("پچژگ".into(), 0)
        );
    }

    #[test]
    fn every_win1256_byte_decodes_exactly() {
        for b in 0x80..=0xFFu8 {
            let buf = [b];
            let r = decode(&buf, Charset::Ar8MsWin1256);
            assert!(r.is_exact(), "0x{b:02X} must be defined in windows-1256");
            assert_ne!(r.text, "\u{FFFD}");
        }
    }

    #[test]
    fn iso8859_6_undefined_bytes_are_flagged() {
        // 0xA1 is undefined in ISO-8859-6; 0xC7 is ALEF.
        assert_eq!(
            d(&[0xC7, 0xA1], Charset::Ar8Iso8859P6),
            ("ا\u{FFFD}".into(), 1)
        );
    }

    #[test]
    fn win1252_undefined() {
        assert_eq!(
            d(&[0x80, 0x81], Charset::We8MsWin1252),
            ("€\u{FFFD}".into(), 1)
        );
    }

    #[test]
    fn utf8_and_cesu8() {
        let s = "فاتورة رقم 15 😀";
        assert_eq!(d(s.as_bytes(), Charset::Al32Utf8), (s.into(), 0));
        // CESU-8 of U+1F600: surrogates D83D DE00 → ED A0 BD ED B8 80
        let cesu = [0xED, 0xA0, 0xBD, 0xED, 0xB8, 0x80];
        assert_eq!(d(&cesu, Charset::Utf8Cesu), ("😀".into(), 0));
        // Surrogates are invalid in AL32UTF8; following Unicode's "maximal
        // subpart" practice each of the 6 bytes is its own ill-formed sequence.
        assert_eq!(d(&cesu, Charset::Al32Utf8).1, 6);
        assert_eq!(d(&[0xC3, 0x28], Charset::Al32Utf8), ("\u{FFFD}(".into(), 1));
        // A lone high surrogate in CESU-8 is flagged.
        assert_eq!(d(&[0xED, 0xA0, 0xBD, 0x41], Charset::Utf8Cesu).1, 1);
    }

    #[test]
    fn al16utf16_is_big_endian() {
        // "عربي" = 0639 0631 0628 064A
        let raw = [0x06, 0x39, 0x06, 0x31, 0x06, 0x28, 0x06, 0x4A];
        assert_eq!(d(&raw, Charset::Al16Utf16), ("عربي".into(), 0));
        assert_eq!(
            d(&[0x06, 0x39, 0x06], Charset::Al16Utf16).1,
            1,
            "odd length flagged"
        );
    }

    #[test]
    fn ascii_fast_path_borrows() {
        let r = decode(b"INV-2026", Charset::Ar8MsWin1256);
        assert!(matches!(r.text, Cow::Borrowed(_)));
    }

    #[test]
    fn ids_and_names_roundtrip() {
        for id in [1u16, 31, 51, 178, 560, 871, 873, 2000] {
            let cs = Charset::from_oracle_id(id).unwrap();
            assert_eq!(Charset::from_oracle_name(cs.oracle_name()), Some(cs));
        }
        assert_eq!(
            Charset::from_oracle_name("ar8mswin1256"),
            Some(Charset::Ar8MsWin1256)
        );
        assert_eq!(Charset::from_oracle_id(9999), None);
    }
}
